136	              kind,
137	              text: value,
138	              confirmedAt: timestamp,
139	            };
140	        if (existing) await requestToPromise(textStore.put(textRecord));
141	        else await requestToPromise(textStore.add(textRecord));
142	        const updatedResume: Resume = {
143	          ...resume,
144	          status: "ready",
145	          textSource: kind === "confirmed" ? "extracted" : "manual",
146	          textConfirmedAt: timestamp,
147	          updatedAt: nextUpdatedTimestamp(timestamp, resume.updatedAt),
148	        };
149	        await requestToPromise(resumeStore.put(updatedResume));
150	        return { resume: updatedResume, text: textRecord };
151	      },
152	    );
153	    return result;
154	  }
